def duplicates(lst):
    seen, dup = set(), set()
    for x in lst:
        if x in seen:
            dup.add(x)
        seen.add(x)
    return sorted(dup)

print(duplicates([1, 2, 3, 2, 4, 3, 3]))   # [2, 3]

def z_filter(df, col, z=3):
    zs = (df[col] - df[col].mean()) / df[col].std()
    return df[zs.abs() <= z]

